store = {}

class TenantStore:
    def __init__(self, tenant):
        self.tenant = tenant
    def _k(self, key):
        return '%s:%s' % (self.tenant, key)  # prefix enforced here, not by callers
    def put(self, key, val):
        store[self._k(key)] = val
    def get(self, key):
        return store.get(self._k(key))

a, b = TenantStore('acme'), TenantStore('globex')
a.put('settings', 'acme-theme')
b.put('settings', 'globex-theme')
print('acme sees:', a.get('settings'))
print('globex sees:', b.get('settings'))
print('raw keys:', sorted(store))

ACL = {  # namespace -> {user: {perms}}
    'acme': {'alice': {'read', 'write'}, 'bob': {'read'}},
    'globex': {'carol': {'read', 'write'}},
}

def can(user, ns, perm):
    return perm in ACL.get(ns, {}).get(user, set())  # deny by default

tests = [('alice', 'acme', 'write'), ('bob', 'acme', 'write'),
         ('bob', 'globex', 'read'), ('carol', 'acme', 'read')]
for u, ns, p in tests:
    print('%-5s %-6s %-5s -> %s' % (u, ns, p, 'ALLOW' if can(u, ns, p) else 'DENY'))

usage, QUOTA = {}, 5

def write(tenant, key, val):
    u = usage.get(tenant, 0)
    if u >= QUOTA:
        return 'REJECTED 429 (quota %d)' % QUOTA
    usage[tenant] = u + 1
    return 'stored (%d/%d)' % (u + 1, QUOTA)

for i in range(7):
    print('acme write %d:' % i, write('acme', 'k%d' % i, 'v'))
print('globex unaffected:', write('globex', 'k0', 'v'))

