import os, hashlib
# envelope encryption, toy cipher (XOR with keystream) standing in for AES-GCM
def keystream(key, n):
    return hashlib.sha256(key).digest() * (n // 32 + 1)

DEKS = {'acme': os.urandom(16), 'globex': os.urandom(16)}

def enc(tenant, pt):
    pt = pt.encode()
    ks = keystream(DEKS[tenant], len(pt))
    return bytes(a ^ b for a, b in zip(pt, ks))

c1 = enc('acme', 'acme-secret')
print('acme ciphertext != globex ciphertext for same plaintext:',
      c1 != enc('globex', 'acme-secret'))
del DEKS['acme']  # crypto-shredding: tenant deleted, data unrecoverable
print('acme DEK destroyed -> their rows are unrecoverable (crypto-shredding)')

data = {'acme': ['acme doc1', 'acme doc2'], 'globex': ['globex doc1']}
audit = []

def search(user, elevated, q):
    if not elevated:
        raise PermissionError('cross-tenant search needs elevation')
    audit.append((user, q))  # every cross-tenant query is logged
    return [(t, d) for t, docs in data.items() for d in docs if q in d]

try:
    search('mallory', False, 'doc1')
except PermissionError as e:
    print('unelevated:', e)
print('elevated :', search('admin', True, 'doc1'))
print('audit log:', audit)

catalog = {'tenants': {}, 'namespaces': {}}

def provision(tenant, tier):
    if tenant in catalog['tenants']:
        raise ValueError('duplicate tenant')
    catalog['tenants'][tenant] = {'tier': tier, 'namespaces': []}
    ns = '%s-default' % tenant
    catalog['namespaces'][ns] = {'tenant': tenant, 'quota_gb': 100 if tier == 'pro' else 5}
    catalog['tenants'][tenant]['namespaces'].append(ns)
    return ns

print('provisioned:', provision('acme', 'pro'))
try:
    provision('acme', 'pro')
except ValueError as e:
    print('duplicate blocked:', e)
print('catalog:', catalog)

from collections import deque

class Pool:
    def __init__(self, size):
        self.free = size
    def acquire(self):
        if self.free:
            self.free -= 1
            return True
        return False

pools = {'acme': Pool(2), 'globex': Pool(2)}
# acme hogs its whole pool...
acme_got = [pools['acme'].acquire() for _ in range(4)]
# ...but globex is unaffected: separate bulkhead
globex_got = [pools['globex'].acquire() for _ in range(2)]
print('acme acquisitions  :', acme_got, '(2 ok, 2 shed)')
print('globex acquisitions:', globex_got, '(untouched bulkhead)')
